        "p": "ODR ринку зріс з <b>19.6%</b> (3 серп) до <b>21.6%</b> (19 жовт) — це +2.0 п.п. за 12 тижнів. Минулий тиждень: 21.6% проти 21.0% тижнем раніше, обсяг 11.4k замовлень (було 11.3k)."
